/**
 * Rechnungen-Tab — CRUD for student invoices (Iteration 30 rewrite).
 *
 * The invoice number is generated by the backend (RE-2026-0001). The
 * form only collects: lesson date, duration (min), price (CHF),
 * payment method (Bar/Rechnung/Kreditkarte/Twint), note, status.
 * Autosave on blur for existing rows. New row via the compact form
 * on top. A "PDF" button per row streams a formatted invoice PDF.
 */
import { useEffect, useMemo, useState } from "react";
import { Loader2, Trash2, Plus, Check, CircleDot, XCircle, FileDown, Mail, Archive } from "lucide-react";
import { toast } from "sonner";
import { api, formatApiError } from "@/lib/api";

const STATUS_META = {
  open:      { label: "Offen",     bg: "#fff7ed", text: "#c2410c", dot: "#f97316" },
  paid:      { label: "Bezahlt",   bg: "#dcfce7", text: "#166534", dot: "#16a34a" },
  cancelled: { label: "Storniert", bg: "#f5f5f4", text: "#57534e", dot: "#a8a29e" },
};

const PAYMENT_META = {
  bar:         { label: "Bar" },
  rechnung:    { label: "Rechnung" },
  kreditkarte: { label: "Kreditkarte" },
  twint:       { label: "Twint" },
};

const formatDMY = (iso) => {
  if (!iso || typeof iso !== "string") return "—";
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(iso);
  return m ? `${m[3]}/${m[2]}/${m[1]}` : "—";
};

const money = (n) =>
  new Intl.NumberFormat("de-CH", {
    style: "currency",
    currency: "CHF",
    minimumFractionDigits: 2,
  }).format(Number(n) || 0);

const backendBase = (process.env.REACT_APP_BACKEND_URL || "").replace(/\/$/, "");

export default function InvoicesTab({ student }) {
  const [invoices, setInvoices] = useState([]);
  const [loading, setLoading] = useState(true);
  const [creating, setCreating] = useState(false);
  const [downloading, setDownloading] = useState(null);
  const [sending, setSending] = useState(null);
  const [draft, setDraft] = useState({
    lesson_date: new Date().toISOString().slice(0, 10),
    duration_min: 45,
    price_chf: "",
    payment_method: "bar",
    status: "open",
    note: "",
  });

  const load = async () => {
    try {
      const r = await api.get(`/students/${student.id}/invoices`);
      setInvoices(r.data);
    } catch (e) {
      toast.error(formatApiError(e));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [student.id]);

  const totals = useMemo(() => {
    const t = { total: 0, open: 0, paid: 0 };
    for (const i of invoices) {
      const price = Number(i.price_chf) || 0;
      if (i.status === "cancelled") continue;
      t.total += price;
      if (i.status === "paid") t.paid += price;
      else if (i.status === "open") t.open += price;
    }
    return t;
  }, [invoices]);

  const createInvoice = async () => {
    if (!draft.price_chf || Number(draft.price_chf) <= 0) {
      toast.error("Bitte Preis angeben");
      return;
    }
    setCreating(true);
    try {
      await api.post(`/students/${student.id}/invoices`, {
        ...draft,
        price_chf: parseFloat(draft.price_chf) || 0,
        duration_min: parseInt(draft.duration_min, 10) || 0,
      });
      toast.success("Rechnung angelegt");
      setDraft({
        lesson_date: new Date().toISOString().slice(0, 10),
        duration_min: 45,
        price_chf: "",
        payment_method: "bar",
        status: "open",
        note: "",
      });
      load();
    } catch (e) {
      toast.error(formatApiError(e));
    } finally {
      setCreating(false);
    }
  };

  const patch = async (id, field, value) => {
    try {
      let v = value;
      if (field === "price_chf") v = parseFloat(value) || 0;
      else if (field === "duration_min") v = parseInt(value, 10) || 0;
      await api.patch(`/students/${student.id}/invoices/${id}`, { [field]: v });
      load();
    } catch (e) {
      toast.error(formatApiError(e));
    }
  };

  const cycleStatus = async (invoice) => {
    const order = ["open", "paid", "cancelled"];
    const next = order[(order.indexOf(invoice.status) + 1) % order.length];
    await patch(invoice.id, "status", next);
  };

  const removeInvoice = async (id) => {
    if (!window.confirm("Rechnung wirklich löschen?")) return;
    try {
      await api.delete(`/students/${student.id}/invoices/${id}`);
      toast.success("Gelöscht");
      load();
    } catch (e) {
      toast.error(formatApiError(e));
    }
  };

  const downloadPdf = async (inv) => {
    setDownloading(inv.id);
    try {
      const res = await api.get(
        `/students/${student.id}/invoices/${inv.id}.pdf`,
        { responseType: "blob" },
      );
      const blob = new Blob([res.data], { type: "application/pdf" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `${inv.number || "Rechnung"}.pdf`;
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 1000);
    } catch (e) {
      toast.error(formatApiError(e));
    } finally {
      setDownloading(null);
    }
  };

  const sendEmail = async (inv) => {
    const defaultTo = student.email || "";
    const to = window.prompt(
      `Rechnung ${inv.number} per E-Mail an:`,
      defaultTo,
    );
    if (to === null) return;                     // cancelled
    if (!to.trim()) {
      toast.error("Bitte Empfänger-E-Mail angeben");
      return;
    }
    setSending(inv.id);
    try {
      await api.post(`/students/${student.id}/invoices/${inv.id}/email`, {
        to: to.trim(),
      });
      toast.success(`E-Mail an ${to.trim()} versendet`);
    } catch (e) {
      toast.error(formatApiError(e));
    } finally {
      setSending(null);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center gap-2 text-sm text-[#78716c]">
        <Loader2 size={14} className="animate-spin" /> Lade Rechnungen …
      </div>
    );
  }

  return (
    <div data-testid="invoices-tab" className="space-y-6">
      <div>
        <h2 className="font-display text-3xl md:text-4xl leading-none tracking-tight">
          Rechnungen
        </h2>
        <p className="text-xs text-[#78716c] mt-2 flex flex-wrap items-center gap-3">
          <span>
            <span className="font-semibold text-[#0f172a]">{invoices.length}</span>{" "}
            {invoices.length === 1 ? "Rechnung" : "Rechnungen"}
          </span>
          <span className="text-[#a8a29e]">·</span>
          <span>
            <span className="font-semibold text-[#0f172a]" data-testid="invoices-total">
              {money(totals.total)}
            </span>{" "}
            gesamt
          </span>
          <span className="text-[#a8a29e]">·</span>
          <span className="text-[#c2410c] font-semibold" data-testid="invoices-open">
            {money(totals.open)} offen
          </span>
          <span className="text-[#a8a29e]">·</span>
          <span className="text-[#166534] font-semibold" data-testid="invoices-paid">
            {money(totals.paid)} bezahlt
          </span>
        </p>
      </div>

      {/* Create form */}
      <div className="bg-white border border-[#e7e5e4] rounded-2xl p-4">
        <div className="text-[10px] font-semibold tracking-widest uppercase text-[#475569] mb-3">
          Neue Rechnung — Nr. wird automatisch generiert
        </div>
        <div className="grid grid-cols-1 md:grid-cols-6 gap-3">
          <FieldGroup label="Datum der Lektion">
            <input
              type="date"
              value={draft.lesson_date}
              onChange={(e) => setDraft({ ...draft, lesson_date: e.target.value })}
              data-testid="invoice-new-lesson-date"
              className="w-full text-sm bg-[#fbf9f6] border border-[#e2e8f0] rounded-lg px-3 py-2 focus:outline-none focus:border-[#ff5a36]"
            />
          </FieldGroup>
          <FieldGroup label="Dauer (min)">
            <input
              type="number"
              min={0}
              value={draft.duration_min}
              onChange={(e) => setDraft({ ...draft, duration_min: e.target.value })}
              data-testid="invoice-new-duration"
              className="w-full text-sm bg-[#fbf9f6] border border-[#e2e8f0] rounded-lg px-3 py-2 focus:outline-none focus:border-[#ff5a36]"
            />
          </FieldGroup>
          <FieldGroup label="Preis CHF">
            <input
              type="number"
              step="0.05"
              value={draft.price_chf}
              onChange={(e) => setDraft({ ...draft, price_chf: e.target.value })}
              placeholder="z. B. 120.00"
              data-testid="invoice-new-price"
              className="w-full text-sm bg-[#fbf9f6] border border-[#e2e8f0] rounded-lg px-3 py-2 focus:outline-none focus:border-[#ff5a36]"
            />
          </FieldGroup>
          <FieldGroup label="Zahlungsweise">
            <select
              value={draft.payment_method}
              onChange={(e) => setDraft({ ...draft, payment_method: e.target.value })}
              data-testid="invoice-new-payment-method"
              className="w-full text-sm bg-[#fbf9f6] border border-[#e2e8f0] rounded-lg px-3 py-2 focus:outline-none focus:border-[#ff5a36]"
            >
              {Object.entries(PAYMENT_META).map(([k, v]) => (
                <option key={k} value={k}>{v.label}</option>
              ))}
            </select>
          </FieldGroup>
          <FieldGroup label="Status">
            <select
              value={draft.status}
              onChange={(e) => setDraft({ ...draft, status: e.target.value })}
              data-testid="invoice-new-status"
              className="w-full text-sm bg-[#fbf9f6] border border-[#e2e8f0] rounded-lg px-3 py-2 focus:outline-none focus:border-[#ff5a36]"
            >
              <option value="open">Offen</option>
              <option value="paid">Bezahlt</option>
              <option value="cancelled">Storniert</option>
            </select>
          </FieldGroup>
          <div className="flex items-end">
            <button
              type="button"
              onClick={createInvoice}
              disabled={creating}
              data-testid="invoice-create-button"
              className="w-full inline-flex items-center justify-center gap-1.5 text-xs font-semibold tracking-widest uppercase bg-[#ff5a36] text-white px-4 py-2.5 rounded-lg hover:opacity-90 disabled:opacity-50"
            >
              {creating ? <Loader2 size={12} className="animate-spin" /> : <Plus size={12} />}
              Anlegen
            </button>
          </div>
        </div>
        <div className="mt-3">
          <FieldGroup label="Bemerkungen (optional)">
            <textarea
              rows={2}
              value={draft.note}
              onChange={(e) => setDraft({ ...draft, note: e.target.value })}
              placeholder="z. B. Zusatzkilometer, Autobahnaufschlag"
              data-testid="invoice-new-note"
              className="w-full text-sm bg-[#fbf9f6] border border-[#e2e8f0] rounded-lg px-3 py-2 focus:outline-none focus:border-[#ff5a36] resize-none"
            />
          </FieldGroup>
        </div>
      </div>

      {/* Invoice rows */}
      {invoices.length === 0 && (
        <div className="bg-white border border-dashed border-[#e7e5e4] rounded-2xl p-10 text-center text-sm text-[#78716c]">
          Noch keine Rechnung erstellt.
        </div>
      )}

      <div className="space-y-2.5">
        {invoices.map((inv) => {
          const st = STATUS_META[inv.status] || STATUS_META.open;
          return (
            <div
              key={inv.id}
              data-testid={`invoice-row-${inv.id}`}
              className="bg-white border border-[#e7e5e4] rounded-2xl p-4"
            >
              <div className="grid grid-cols-1 md:grid-cols-[120px_130px_100px_120px_140px_120px_1fr_auto] items-center gap-3">
                <div>
                  <label className="text-[9px] tracking-widest uppercase text-[#94a3b8] block">
                    Rechnungsnr.
                  </label>
                  <div
                    className="text-sm font-semibold text-[#0f172a]"
                    data-testid={`invoice-number-${inv.id}`}
                  >
                    {inv.number || "—"}
                  </div>
                </div>
                <div>
                  <label className="text-[9px] tracking-widest uppercase text-[#94a3b8] block">
                    Datum Lektion
                  </label>
                  <input
                    type="date"
                    defaultValue={inv.lesson_date}
                    onBlur={(e) => e.target.value !== inv.lesson_date && patch(inv.id, "lesson_date", e.target.value)}
                    data-testid={`invoice-lesson-date-${inv.id}`}
                    className="text-sm border-0 bg-transparent focus:outline-none focus:border-b focus:border-[#ff5a36]"
                  />
                  <div className="text-[10px] text-[#a8a29e]">{formatDMY(inv.lesson_date)}</div>
                </div>
                <div>
                  <label className="text-[9px] tracking-widest uppercase text-[#94a3b8] block">
                    Dauer
                  </label>
                  <input
                    type="number"
                    min={0}
                    defaultValue={inv.duration_min}
                    onBlur={(e) => Number(e.target.value) !== Number(inv.duration_min) && patch(inv.id, "duration_min", e.target.value)}
                    data-testid={`invoice-duration-${inv.id}`}
                    className="text-sm border-0 bg-transparent focus:outline-none focus:border-b focus:border-[#ff5a36] w-16"
                  />
                  <span className="text-[10px] text-[#a8a29e] ml-1">min</span>
                </div>
                <div>
                  <label className="text-[9px] tracking-widest uppercase text-[#94a3b8] block">
                    Preis CHF
                  </label>
                  <input
                    type="number"
                    step="0.05"
                    defaultValue={inv.price_chf}
                    onBlur={(e) => Number(e.target.value) !== Number(inv.price_chf) && patch(inv.id, "price_chf", e.target.value)}
                    data-testid={`invoice-price-${inv.id}`}
                    className="text-sm font-semibold text-[#0f172a] border-0 bg-transparent focus:outline-none focus:border-b focus:border-[#ff5a36] w-24"
                  />
                </div>
                <div>
                  <label className="text-[9px] tracking-widest uppercase text-[#94a3b8] block">
                    Zahlungsweise
                  </label>
                  <select
                    defaultValue={inv.payment_method}
                    onChange={(e) => e.target.value !== inv.payment_method && patch(inv.id, "payment_method", e.target.value)}
                    data-testid={`invoice-payment-method-${inv.id}`}
                    className="text-sm border-0 bg-transparent focus:outline-none focus:border-b focus:border-[#ff5a36]"
                  >
                    {Object.entries(PAYMENT_META).map(([k, v]) => (
                      <option key={k} value={k}>{v.label}</option>
                    ))}
                  </select>
                </div>
                <button
                  onClick={() => cycleStatus(inv)}
                  data-testid={`invoice-status-${inv.id}`}
                  className="inline-flex items-center gap-1.5 text-[10px] font-semibold tracking-widest uppercase px-3 py-1.5 rounded-full transition-colors self-start"
                  style={{ background: st.bg, color: st.text }}
                >
                  {inv.status === "paid" && <Check size={11} strokeWidth={3} />}
                  {inv.status === "open" && <CircleDot size={11} />}
                  {inv.status === "cancelled" && <XCircle size={11} />}
                  {st.label}
                </button>
                <input
                  type="text"
                  defaultValue={inv.note}
                  onBlur={(e) => e.target.value !== inv.note && patch(inv.id, "note", e.target.value)}
                  data-testid={`invoice-note-${inv.id}`}
                  placeholder="Bemerkungen"
                  className="text-sm text-[#334155] border-0 bg-transparent focus:outline-none focus:border-b focus:border-[#ff5a36] min-w-0"
                />
                <div className="flex items-center gap-1">
                  <button
                    onClick={() => downloadPdf(inv)}
                    disabled={downloading === inv.id}
                    data-testid={`invoice-download-pdf-${inv.id}`}
                    className="inline-flex items-center gap-1 text-[10px] font-semibold tracking-widest uppercase bg-[#0f172a] text-white px-3 py-2 rounded-full hover:opacity-90 disabled:opacity-40"
                  >
                    {downloading === inv.id ? (
                      <Loader2 size={11} className="animate-spin" />
                    ) : (
                      <FileDown size={11} />
                    )}
                    PDF
                  </button>
                  {inv.archive_url && (
                    <a
                      href={`${backendBase}${inv.archive_url}`}
                      target="_blank"
                      rel="noreferrer"
                      data-testid={`invoice-archive-${inv.id}`}
                      title={`Aus Archiv laden – ${inv.archived_at?.slice(0, 10) || ""}`}
                      className="inline-flex items-center gap-1 text-[10px] font-semibold tracking-widest uppercase text-[#475569] bg-white border border-[#e2e8f0] px-2.5 py-2 rounded-full hover:text-[#0f172a] hover:border-[#0f172a]"
                    >
                      <Archive size={11} />
                    </a>
                  )}
                  <button
                    onClick={() => sendEmail(inv)}
                    disabled={sending === inv.id}
                    data-testid={`invoice-send-email-${inv.id}`}
                    className="inline-flex items-center gap-1 text-[10px] font-semibold tracking-widest uppercase bg-[#ff5a36] text-white px-3 py-2 rounded-full hover:opacity-90 disabled:opacity-40"
                    title="Rechnung per E-Mail senden"
                  >
                    {sending === inv.id ? (
                      <Loader2 size={11} className="animate-spin" />
                    ) : (
                      <Mail size={11} />
                    )}
                    E-Mail
                  </button>
                  <button
                    onClick={() => removeInvoice(inv.id)}
                    data-testid={`invoice-delete-${inv.id}`}
                    className="w-8 h-8 flex items-center justify-center rounded-full text-[#a8a29e] hover:text-[#dc2626] hover:bg-[#fee2e2]"
                  >
                    <Trash2 size={13} />
                  </button>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function FieldGroup({ label, children }) {
  return (
    <div>
      <label className="text-[10px] tracking-widest uppercase text-[#475569] font-semibold block mb-1">
        {label}
      </label>
      {children}
    </div>
  );
}
